16	// ----------------------------------------------------------------------------
17	// Transformer model
18	
19	typedef struct {
20	    int dim; // transformer dimension
21	    int hidden_dim; // for ffn layers
22	    int n_layers; // number of layers
23	    int n_heads; // number of query heads
24	    int n_kv_heads; // number of key/value heads (can be < query heads because of multiquery)
25	    int vocab_size; // vocabulary size, usually 256 (byte-level)
26	    int seq_len; // max sequence length
27	} Config;
28	
29	typedef struct {
30	    // token embedding table
31	    float* token_embedding_table;    // (vocab_size, dim)
32	    // weights for rmsnorms
33	    float* rms_att_weight; // (layer, dim) rmsnorm weights
34	    float* rms_ffn_weight; // (layer, dim)
35	    // weights for matmuls. note dim == n_heads * head_size
36	    float* wq; // (layer, dim, n_heads * head_size)
37	    float* wk; // (layer, dim, n_kv_heads * head_size)
38	    float* wv; // (layer, dim, n_kv_heads * head_size)
39	    float* wo; // (layer, n_heads * head_size, dim)
40	    // weights for ffn
41	    float* w1; // (layer, hidden_dim, dim)
42	    float* w2; // (layer, dim, hidden_dim)
43	    float* w3; // (layer, hidden_dim, dim)
44	    // final rmsnorm
45	    float* rms_final_weight; // (dim,)
46	    // (optional) classifier weights for the logits, on the last layer
47	    float* wcls;
48	} TransformerWeights;
49	
50	typedef struct {
51	    // current wave of activations
52	    float *x; // activation at current time stamp (dim,)
53	    float *xb; // same, but inside a residual branch (dim,)
54	    float *xb2; // an additional buffer just for convenience (dim,)
55	    float *hb; // buffer for hidden dimension in the ffn (hidden_dim,)
56	    float *hb2; // buffer for hidden dimension in the ffn (hidden_dim,)
57	    float *q; // query (dim,)
58	    float *k; // key (dim,)
59	    float *v; // value (dim,)
60	    float *att; // buffer for scores/attention values (n_heads, seq_len)
61	    float *logits; // output logits
62	    // kv cache
63	    float* key_cache;   // (layer, seq_len, dim)
64	    float* value_cache; // (layer, seq_len, dim)
65	} RunState;
66	
67	typedef struct {
68	    Config config; // the hyperparameters of the architecture (the blueprint)
69	    TransformerWeights weights; // the weights of the model
70	    RunState state; // buffers for the "wave" of activations in the forward pass
71	    // some more state needed to properly clean up the memory mapping (sigh)
72	    int fd; // file descriptor for memory mapping
73	    float* data; // memory mapped data pointer
74	    ssize_t file_size; // size of the checkpoint file in bytes
75	} Transformer;
76	
77	void malloc_run_state(RunState* s, Config* p) {
78	    // we calloc instead of malloc to keep valgrind happy
79	    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
80	    s->x = calloc(p->dim, sizeof(float));
81	    s->xb = calloc(p->dim, sizeof(float));
82	    s->xb2 = calloc(p->dim, sizeof(float));
83	    s->hb = calloc(p->hidden_dim, sizeof(float));
84	    s->hb2 = calloc(p->hidden_dim, sizeof(float));
85	    s->q = calloc(p->dim, sizeof(float));
86	    s->key_cache = calloc(p->n_layers * p->seq_len * kv_dim, sizeof(float));
87	    s->value_cache = calloc(p->n_layers * p->seq_len * kv_dim, sizeof(float));
88	    s->att = calloc(p->n_heads * p->seq_len, sizeof(float));
89	    s->logits = calloc(p->vocab_size, sizeof(float));
90	    // ensure all mallocs went fine
91	    if (!s->x || !s->xb || !s->xb2 || !s->hb || !s->hb2 || !s->q
92	     || !s->key_cache || !s->value_cache || !s->att || !s->logits) {
93	        fprintf(stderr, "malloc failed!\n");
94	        exit(EXIT_FAILURE);
95	    }
96	}
97	
98	void free_run_state(RunState* s) {
99	    free(s->x);
100	    free(s->xb);
101	    free(s->xb2);
102	    free(s->hb);
103	    free(s->hb2);
104	    free(s->q);
105	    free(s->att);
106	    free(s->logits);
107	    free(s->key_cache);
108	    free(s->value_cache);
109	}
110	
111	void memory_map_weights(TransformerWeights *w, Config* p, float* ptr, int shared_weights) {
112	    int head_size = p->dim / p->n_heads;
113	    // make sure the multiplications below are done in 64bit to fit the parameter counts of 13B+ models
114	    unsigned long long n_layers = p->n_layers;
115	    w->token_embedding_table = ptr;
116	    ptr += p->vocab_size * p->dim;
117	    w->rms_att_weight = ptr;
118	    ptr += n_layers * p->dim;
119	    w->wq = ptr;
120	    ptr += n_layers * p->dim * (p->n_heads * head_size);
121	    w->wk = ptr;
122	    ptr += n_layers * p->dim * (p->n_kv_heads * head_size);
123	    w->wv = ptr;
124	    ptr += n_layers * p->dim * (p->n_kv_heads * head_size);
125	    w->wo = ptr;
126	    ptr += n_layers * (p->n_heads * head_size) * p->dim;
127	    w->rms_ffn_weight = ptr;
128	    ptr += n_layers * p->dim;
129	    w->w1 = ptr;
130	    ptr += n_layers * p->dim * p->hidden_dim;
131	    w->w2 = ptr;
132	    ptr += n_layers * p->hidden_dim * p->dim;
133	    w->w3 = ptr;
134	    ptr += n_layers * p->dim * p->hidden_dim;
135	    w->rms_final_weight = ptr;
136	    ptr += p->dim;
137	    ptr += p->seq_len * head_size / 2; // skip what used to be freq_cis_real (for RoPE)
138	    ptr += p->seq_len * head_size / 2; // skip what used to be freq_cis_imag (for RoPE)
139	    w->wcls = shared_weights ? w->token_embedding_table : ptr;
140	}
141	
142	void read_checkpoint(char* checkpoint, Config* config, TransformerWeights* weights,
143	                     int* fd, float** data, ssize_t* file_size) {
144	    FILE *file = fopen(checkpoint, "rb");
145	    if (!file) { fprintf(stderr, "Couldn't open file %s\n", checkpoint); exit(EXIT_FAILURE); }
146	    // read in the config header
147	    if (fread(config, sizeof(Config), 1, file) != 1) { exit(EXIT_FAILURE); }
148	    // negative vocab size is hacky way of signaling unshared weights. bit yikes.
149	    int shared_weights = config->vocab_size > 0 ? 1 : 0;
150	    config->vocab_size = abs(config->vocab_size);
151	    // figure out the file size
152	    fseek(file, 0, SEEK_END); // move file pointer to end of file
153	    *file_size = ftell(file); // get the file size, in bytes
154	    fclose(file);
155	    // memory map the Transformer weights into the data pointer
156	    *fd = open(checkpoint, O_RDONLY); // open in read only mode
157	    if (*fd == -1) { fprintf(stderr, "open failed!\n"); exit(EXIT_FAILURE); }
158	    *data = mmap(NULL, *file_size, PROT_READ, MAP_PRIVATE, *fd, 0);
159	    if (*data == MAP_FAILED) { fprintf(stderr, "mmap failed!\n"); exit(EXIT_FAILURE); }
160	    float* weights_ptr = *data + sizeof(Config)/sizeof(float);
161	    memory_map_weights(weights, config, weights_ptr, shared_weights);
162	}
163	
164	void build_transformer(Transformer *t, char* checkpoint_path) {
165	    // read in the Config and the Weights from the checkpoint
166	    read_checkpoint(checkpoint_path, &t->config, &t->weights, &t->fd, &t->data, &t->file_size);
167	    // allocate the RunState buffers
168	    malloc_run_state(&t->state, &t->config);
169	}
170	
171	void free_transformer(Transformer* t) {
172	    // close the memory mapping
173	    if (t->data != MAP_FAILED) { munmap(t->data, t->file_size); }
174	    if (t->fd != -1) { close(t->fd); }
175	    // free the RunState buffers
176	    free_run_state(&t->state);
177	}
178	
179	// ----------------------------------------------------------------------------
180	// neural net blocks; the dynamics of the Transformer
181	
182	void rmsnorm(float* o, float* x, float* weight, int size) {
183	    // calculate sum of squares
184	    float ss = 0.0f;
185	    for (int j = 0; j < size; j++) {
186	        ss += x[j] * x[j];
187	    }
188	    ss /= size;
189	    ss += 1e-5f;
190	    ss = 1.0f / sqrtf(ss);
191	    // normalize and scale
192	    for (int j = 0; j < size; j++) {
193	        o[j] = weight[j] * (ss * x[j]);
194	    }
195	}
196	
197	void softmax(float* x, int size) {
198	    // find max value (for numerical stability)
199	    float max_val = x[0];
200	    for (int i = 1; i < size; i++) {
201	        if (x[i] > max_val) {
202	            max_val = x[i];
203	        }
204	    }
205	    // exp and sum
206	    float sum = 0.0f;
207	    for (int i = 0; i < size; i++) {
208	        x[i] = expf(x[i] - max_val);
209	        sum += x[i];
210	    }
211	    // normalize
212	    for (int i = 0; i < size; i++) {
213	        x[i] /= sum;
214	    }
215	}
216	
217	void matmul(float* xout, float* x, float* w, int n, int d) {
218	    // W (d,n) @ x (n,) -> xout (d,)
219	    // by far the most amount of time is spent inside this little function
220	    int i;
221	    #pragma omp parallel for private(i)
222	    for (i = 0; i < d; i++) {
223	        float val = 0.0f;
224	        for (int j = 0; j < n; j++) {
225	            val += w[i * n + j] * x[j];
226	        }
227	        xout[i] = val;
228	    }
229	}
230	
231	float* forward(Transformer* transformer, int token, int pos) {
232	
233	    // a few convenience variables
234	    Config* p = &transformer->config;
235	    TransformerWeights* w = &transformer->weights;
236	    RunState* s = &transformer->state;
237	    float *x = s->x;
238	    int dim = p->dim;
239	    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
240	    int kv_mul = p->n_heads / p->n_kv_heads; // integer multiplier of the kv sharing in multiquery
241	    int hidden_dim =  p->hidden_dim;
242	    int head_size = dim / p->n_heads;
243	
244	    // copy the token embedding into x
245	    float* content_row = w->token_embedding_table + token * dim;
246	    memcpy(x, content_row, dim*sizeof(*x));
247	
248	    // forward all the layers
249	    for(unsigned long long l = 0; l < p->n_layers; l++) {
250	
251	        // attention rmsnorm
252	        rmsnorm(s->xb, x, w->rms_att_weight + l*dim, dim);
253	
254	        // key and value point to the kv cache
255	        int loff = l * p->seq_len * kv_dim; // kv cache layer offset for convenience
256	        s->k = s->key_cache + loff + pos * kv_dim;
257	        s->v = s->value_cache + loff + pos * kv_dim;
258	
259	        // qkv matmuls for this position
260	        matmul(s->q, s->xb, w->wq + l*dim*dim, dim, dim);
261	        matmul(s->k, s->xb, w->wk + l*dim*kv_dim, dim, kv_dim);
262	        matmul(s->v, s->xb, w->wv + l*dim*kv_dim, dim, kv_dim);
263	
264	        // RoPE relative positional encoding: complex-valued rotate q and k in each head
265	        for (int i = 0; i < dim; i+=2) {
266	            int head_dim = i % head_size;
267	            float freq = 1.0f / powf(10000.0f, head_dim / (float)head_size);
268	            float val = pos * freq;
269	            float fcr = cosf(val);
270	            float fci = sinf(val);
271	            int rotn = i < kv_dim ? 2 : 1; // how many vectors? 2 = q & k, 1 = q only
272	            for (int v = 0; v < rotn; v++) {
273	                float* vec = v == 0 ? s->q : s->k; // the vector to rotate (query or key)
274	                float v0 = vec[i];
275	                float v1 = vec[i+1];
276	                vec[i]   = v0 * fcr - v1 * fci;
277	                vec[i+1] = v0 * fci + v1 * fcr;
278	            }
279	        }
280	
281	        // multihead attention. iterate over all heads
282	        int h;
283	        #pragma omp parallel for private(h)
284	        for (h = 0; h < p->n_heads; h++) {
285	            // get the query vector for this head
286	            float* q = s->q + h * head_size;
287	            // attention scores for this head
288	            float* att = s->att + h * p->seq_len;
289	            // iterate over all timesteps, including the current one
290	            for (int t = 0; t <= pos; t++) {
291	                // get the key vector for this head and at this timestep
292	                float* k = s->key_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
293	                // calculate the attention score as the dot product of q and k
294	                float score = 0.0f;
295	                for (int i = 0; i < head_size; i++) {
296	                    score += q[i] * k[i];
297	                }
298	                score /= sqrtf(head_size);
299	                // save the score to the attention buffer
300	                att[t] = score;
301	            }
302	
303	            // softmax the scores to get attention weights, from 0..pos inclusively
304	            softmax(att, pos + 1);
305	
306	            // weighted sum of the values, store back into xb
307	            float* xb = s->xb + h * head_size;
308	            memset(xb, 0, head_size * sizeof(float));
309	            for (int t = 0; t <= pos; t++) {
310	                // get the value vector for this head and at this timestep
311	                float* v = s->value_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
312	                // get the attention weight for this timestep
313	                float a = att[t];
314	                // accumulate the weighted value into xb
315	                for (int i = 0; i < head_size; i++) {
316	                    xb[i] += a * v[i];
317	                }
318	            }
319	        }
320	
321	        // final matmul to get the output of the attention
322	        matmul(s->xb2, s->xb, w->wo + l*dim*dim, dim, dim);
323	
324	        // residual connection back into x
325	        for (int i = 0; i < dim; i++) {
326	            x[i] += s->xb2[i];
327	        }
328	
329	        // ffn rmsnorm
330	        rmsnorm(s->xb, x, w->rms_ffn_weight + l*dim, dim);
331	
332	        // Now for FFN in PyTorch we have: self.w2(F.silu(self.w1(x)) * self.w3(x))
333	        // first calculate self.w1(x) and self.w3(x)
334	        matmul(s->hb, s->xb, w->w1 + l*dim*hidden_dim, dim, hidden_dim);
335	        matmul(s->hb2, s->xb, w->w3 + l*dim*hidden_dim, dim, hidden_dim);
336	
337	        // SwiGLU non-linearity
338	        for (int i = 0; i < hidden_dim; i++) {
339	            float val = s->hb[i];
340	            // silu(x)=x*σ(x), where σ(x) is the logistic sigmoid
341	            val *= (1.0f / (1.0f + expf(-val)));
342	            // elementwise multiply with w3(x)
343	            val *= s->hb2[i];
344	            s->hb[i] = val;
345	        }
346	
347	        // final matmul to get the output of the ffn
348	        matmul(s->xb, s->hb, w->w2 + l*dim*hidden_dim, hidden_dim, dim);
349	
350	        // residual connection
351	        for (int i = 0; i < dim; i++) {
352	            x[i] += s->xb[i];
353	        }
354	    }
355	
356	    // final rmsnorm
357	    rmsnorm(x, x, w->rms_final_weight, dim);
358	
359	    // classifier into logits
360	    matmul(s->logits, x, w->wcls, p->dim, p->vocab_size);
361	    return s->logits;
362	}
